  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Fills water tiles up to the specified distance from the source using breadth-first expansion.
   * Algorithm: 
   *   1. If this is the first call (prevFilledDistance == null), call fillBeginTile() to mark source as filled.
   *   2. For each distance step from (prevFilledDistance + 1) to the given distance:
   *      a. For each currently filled tile, examine its four neighbors.
   *      b. If a neighbor contains a pipe or termination cell, check connectivity:
   *         - The outgoing direction from the current tile must match the opposite direction of the neighbor's connection.
   *      c. If connected and not already filled, mark the neighbor as filled and add to filledTiles list.
   *   3. Update prevFilledDistance to the given distance.
   *   4. Update prevFilledTiles count for loss detection.
   * Related Features: filledTiles (List<Coordinate>), prevFilledDistance (Integer), prevFilledTiles (int), sourceCell (TerminationCell), sinkCell (TerminationCell), cell array
   * Related Classes: Coordinate, TerminationCell, Pipe, Direction, Pa19Helper
   * Input: distance : int - the new maximum fill distance from source
   * Output: void
   * Pre-condition: distance >= 0
   * Post-condition: Water may have expanded to new tiles up to the given distance. Filled tiles are updated.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public void fillTiles(final int distance)
  {
    // 1. If this is the first call, call fillBeginTile()
    if (getPrevFilledDistance() == null) {
      fillBeginTile();
    }
    
    Pa19Helper helper = Pa19Factory.eINSTANCE.createPa19Helper();
    
    // 2. For each distance step from (prevFilledDistance + 1) to the given distance
    int startStep = getPrevFilledDistance() + 1;
    for (int step = startStep; step <= distance; step++) {
      // Take a snapshot of currently filled tiles
      EList<Coordinate> currentFilledTiles = new BasicEList<Coordinate>();
      currentFilledTiles.addAll(getFilledTiles());
      
      // a. For each currently filled tile, examine its four neighbors
      for (Coordinate filledCoord : currentFilledTiles) {
        Cell currentCell = getCell()[filledCoord.getRow()][filledCoord.getCol()];
        
        // Check each of the four directions
        for (Direction dir : Direction.VALUES) {
          Coordinate offset = helper.getOffset(dir);
          Coordinate neighborCoord = filledCoord.add(offset);
          int nRow = neighborCoord.getRow();
          int nCol = neighborCoord.getCol();
          
          // Ensure neighbor is within bounds
          if (nRow < 0 || nRow >= getRows() || nCol < 0 || nCol >= getCols()) {
            continue;
          }
          
          Cell neighborCell = getCell()[nRow][nCol];
          
          // b. If a neighbor contains a pipe or termination cell, check connectivity
          boolean canConnect = false;
          
          if (neighborCell instanceof FillableCell) {
            FillableCell fillableNeighbor = (FillableCell) neighborCell;
            Pipe neighborPipe = fillableNeighbor.getPipe();
            if (neighborPipe != null) {
              // Check if the neighbor pipe has a connection in the opposite direction
              Direction oppositeDir = helper.getOpposite(dir);
              if (neighborPipe.getConnections().contains(oppositeDir)) {
                canConnect = true;
              }
            }
          } else if (neighborCell instanceof TerminationCell) {
            TerminationCell termNeighbor = (TerminationCell) neighborCell;
            Direction oppositeDir = helper.getOpposite(dir);
            if (termNeighbor.getPointingTo() == oppositeDir) {
              canConnect = true;
            }
          }
          
          // c. If connected and not already filled, mark as filled
          if (canConnect) {
            // Check if already filled
            boolean alreadyFilled = false;
            for (Coordinate filled : getFilledTiles()) {
              if (filled.equals(neighborCoord)) {
                alreadyFilled = true;
                break;
              }
            }
            if (!alreadyFilled) {
              getFilledTiles().add(neighborCoord);
            }
          }
        }
      }
    }
    
    // 3. Update prevFilledDistance to the given distance
    setPrevFilledDistance(distance);
    // 4. Update prevFilledTiles count for loss detection
    setPrevFilledTiles(getFilledTiles().size());
  }

